//! Independent life/modal boundaries, deliberately separate from passed matrices.
use gielinor_world::{assembly::{Recipe,PreciseRecipe},inventory::Item,stats::Stats,npc::RandomSource,simulation::{World,PlayerData,WorldEvent},held_use::{Handler,Scope,Type,Request},hits::{Hit,Target,Style},CoordGrid};
struct NoDraw;impl RandomSource for NoDraw{fn below(&mut self,_:u32)->u32{panic!("assembly drew RNG")}}
fn scenario(i:usize,reverse:bool,mode:u8,late:bool){let(orb,out,level,xp)=[(571,1395,54,1000),(575,1399,58,1125),(569,1393,62,1250),(573,1397,66,1375)][i];let r=PreciseRecipe{recipe:Recipe{first:1391,second:orb,output:out,skill:12,level,base_xp:0,members:true},xp_tenths:xp,ticks:2,animation:Some(7531),spot:None};let mut stats=Stats::default();stats.set_base(3,10);stats.set_current(3,10);stats.set_base(12,99);stats.set_current(12,99);stats.set_fine_xp(12,130344311).unwrap();let mut w=World::default();w.collision.allocate(3200,3200,0);let mut d=PlayerData::new(1,"Independent crafting life boundary".into(),CoordGrid::new(3200,3200,0).unwrap(),stats);d.xp_rate_hundreds=125;for(s,id)in[(5,1391),(19,orb),(21,orb),(23,1391)]{d.inventory.restore_slot(s,Some(Item{id,count:1,vars:0})).unwrap();}w.queue_login(1,d).unwrap();w.tick().unwrap();let a=w.actors().next().unwrap();w.set_membership(a,true).unwrap();for id in[1391,orb]{w.held_use_types.insert(id,Type{id,content:-1});}w.held_use_handlers.register(Scope::Types,1391,orb,Handler::AssemblyPrecise(r)).unwrap();w.drain_events();let h=if reverse{Request{selected_slot:19,selected_id:orb,target_slot:5,target_id:1391}}else{Request{selected_slot:5,selected_id:1391,target_slot:19,target_id:orb}};
 if late{w.prepare_held_use(a,h).unwrap();w.finish_held_use(a,h).unwrap();}
 match mode{0=>w.data_mut(a).unwrap().stats.set_current(3,0),1=>{w.queue_hit(Target::Player(a),Hit{display:None,source:None,style:Style::Typeless,damage:20},1).unwrap();w.tick_with_random(&mut NoDraw).unwrap();assert_eq!(w.data(a).unwrap().stats.current(3),0);assert!(w.drain_events().iter().any(|e|matches!(e,WorldEvent::DeathRequested(_))));w.data_mut(a).unwrap().stats.set_current(3,10);},_=>{w.set_modal_open(a,true).unwrap();}}
 let before=w.data(a).unwrap().clone();if !late{if w.prepare_held_use(a,h).is_ok(){let _=w.finish_held_use(a,h);}}
 for _ in 0..8{w.tick_with_random(&mut NoDraw).unwrap();}let d=w.data(a).unwrap();println!("PG_BATTLESTAFF_LIFE profile={i} reverse={reverse} mode={mode} late={late} hp={} output_count={} fine_delta={} inventory_unchanged={}",d.stats.current(3),d.inventory.slots().iter().flatten().filter(|v|v.id==out).count(),d.stats.fine_xp(12)-before.stats.fine_xp(12),d.inventory==before.inventory);assert_eq!(d.inventory,before.inventory,"profile{i} reverse{reverse} mode{mode} late{late}");assert_eq!(d.stats,before.stats,"profile{i} reverse{reverse} mode{mode} late{late}");}
#[test]fn zero_hp_before_action_cannot_craft(){for i in 0..4{for reverse in[false,true]{scenario(i,reverse,0,false);}}}
#[test]fn queued_death_with_visible_hp_restored_before_action_cannot_craft(){for i in 0..4{for reverse in[false,true]{scenario(i,reverse,1,false);}}}
#[test]fn modal_after_admission_cancels_without_credit(){for i in 0..4{for reverse in[false,true]{scenario(i,reverse,2,true);}}}
#[test]fn zero_hp_before_pending_credit_cannot_craft(){for i in 0..4{for reverse in[false,true]{scenario(i,reverse,0,true);}}}
#[test]fn queued_death_cancels_pending_credit_even_if_visible_hp_restored(){for i in 0..4{for reverse in[false,true]{scenario(i,reverse,1,true);}}}
